private static int link(List<String> args) throws UserError, IOException {
    if (args.size() == 0) {
        throw new UserError("Need a file to link.");
    }
    String s = args.get(0);
    List<String> rest = args.subList(1, args.size());

    if (s.startsWith("-")) {
        if (s.equals("-debug")){
            rest = Debug.parseOptions(rest);
        }
        else
            invalidFlag(s, "link");
        return link(rest);
    } else {
        if (! s.endsWith(".fss")) {
